44	export function getFindingsFilterDisplayValue(
45	  filterKey: string,
46	  value: string,
47	  options: GetFindingsFilterDisplayValueOptions = {},
48	): string {
49	  if (!value) return value;
50	  if (filterKey === "filter[provider_type__in]") {
51	    return getProviderDisplayName(value);
52	  }
53	  if (filterKey === "filter[provider_id__in]") {
54	    return getProviderAccountDisplayValue(value, options.providers || []);
55	  }
56	  if (filterKey === "filter[scan__in]" || filterKey === "filter[scan]") {
57	    return getScanDisplayValue(value, options.scans || []);
58	  }
59	  if (filterKey === "filter[severity__in]") {
60	    return (
61	      SEVERITY_DISPLAY_NAMES[
62	        value.toLowerCase() as keyof typeof SEVERITY_DISPLAY_NAMES
63	      ] ?? formatLabel(value)
64	    );
65	  }
66	  if (filterKey === "filter[status__in]") {
67	    return (
68	      FINDING_STATUS_DISPLAY_NAMES[
69	        value as keyof typeof FINDING_STATUS_DISPLAY_NAMES
70	      ] ?? formatLabel(value)
71	    );
72	  }
73	  if (filterKey === "filter[delta__in]" || filterKey === "filter[delta]") {
74	    return (
75	      FINDING_DELTA_DISPLAY_NAMES[value.toLowerCase()] ?? formatLabel(value)
76	    );
77	  }
78	  if (filterKey === "filter[category__in]") {
79	    return getCategoryLabel(value);
80	  }
81	  if (filterKey === "filter[resource_groups__in]") {
82	    return getGroupLabel(value);
83	  }
84	  if (
85	    filterKey === "filter[inserted_at]" ||
86	    filterKey === "filter[inserted_at__gte]" ||
87	    filterKey === "filter[inserted_at__lte]"
88	  ) {
89	    return value;
90	  }
91	
92	  return formatLabel(value);
