 * Sort-token constants for the findings surfaces.
 *
 * There are two distinct families of sort tokens because the two APIs order
 * their columns differently:
 *
 * - **Family A — plain findings.** `status` and `severity` are backed by
 *   Postgres ENUM columns whose *ascending* order already puts the most
 *   important results (FAIL, critical) first, so these tokens carry NO minus
 *   prefix.
 * - **Family B — finding-groups.** The grouped API exposes integer-weighted
 *   computed columns, so *descending* order is needed to surface FAIL,
 *   critical and `new` results first — these tokens are always minus-prefixed.
 *
 * Keeping these here (rather than in a server action) means action and
 * component code can import the tokens without pulling in server-only
 * authentication code.
 */

// ---------------------------------------------------------------------------
// Family A — plain findings (Postgres ENUM, ascending = FAIL/critical first)
// ---------------------------------------------------------------------------

/** Order plain findings so FAIL comes first (ascending ENUM order). */
export const FINDINGS_FAIL_FIRST = "status";
/** Order plain findings so the highest severity comes first. */
export const FINDINGS_SEVERITY_HIGH_FIRST = "severity";
/** Most recently inserted findings first. */
export const FINDINGS_RECENT_INSERT = "-inserted_at";
/** Most recently updated findings first. */
export const FINDINGS_RECENT_UPDATE = "-updated_at";

// ---------------------------------------------------------------------------
// Family B — finding-groups (integer-weighted columns, descending = first)
// ---------------------------------------------------------------------------

/** Order finding-groups so FAIL comes first (descending weighted order). */
export const FG_FAIL_FIRST = "-status";
/** Order finding-groups so the highest severity comes first. */
export const FG_SEVERITY_HIGH_FIRST = "-severity";
/** Surface groups whose delta is `new` first. */
export const FG_DELTA_NEW_FIRST = "-delta";
/** Most recently seen groups first. */
export const FG_RECENT_LAST_SEEN = "-last_seen_at";

// ---------------------------------------------------------------------------
// Composition helper
// ---------------------------------------------------------------------------

/**
 * Joins sort token strings with commas, in the order given. The leftmost token
 * has the highest sort precedence (JSON:API rule). Returns an empty string when
 * called with no arguments.
 */
export function composeSort(...tokens: string[]): string {
  return tokens.join(",");
}

// ---------------------------------------------------------------------------
// Preset composite sort strings — Family A (plain findings)
// ---------------------------------------------------------------------------

/**
 * Default sort for the plain findings list. No `delta` — plain findings do not
 * expose that field.
 */
export const FINDINGS_DEFAULT_SORT = composeSort(
  FINDINGS_FAIL_FIRST,
  FINDINGS_SEVERITY_HIGH_FIRST,
  FINDINGS_RECENT_INSERT,
); // "status,severity,-inserted_at"

/**
 * Sort for findings when a status filter is already applied by the API call, so
 * `status` is omitted from the sort.
 */
export const FINDINGS_FILTERED_SORT = composeSort(
  FINDINGS_SEVERITY_HIGH_FIRST,
  FINDINGS_RECENT_INSERT,
); // "severity,-inserted_at"

/**
 * Sort for the "other findings" list in the resource drawer. Uses `updated_at`
 * because the latest-findings endpoint exposes it.
 */
export const RESOURCE_DRAWER_OTHER_FINDINGS_SORT = composeSort(
  FINDINGS_SEVERITY_HIGH_FIRST,
  FINDINGS_RECENT_UPDATE,
); // "severity,-updated_at"

// ---------------------------------------------------------------------------
// Preset composite sort strings — Family B (finding-groups)
// ---------------------------------------------------------------------------

/** Default sort for the finding-groups list. */
export const FINDING_GROUPS_DEFAULT_SORT = composeSort(
  FG_FAIL_FIRST,
  FG_SEVERITY_HIGH_FIRST,
  FG_DELTA_NEW_FIRST,
  FG_RECENT_LAST_SEEN,
); // "-status,-severity,-delta,-last_seen_at"

/** Default sort for the resources inside a finding-group (same shape). */
export const FINDING_GROUP_RESOURCES_DEFAULT_SORT = composeSort(
  FG_FAIL_FIRST,
  FG_SEVERITY_HIGH_FIRST,
  FG_DELTA_NEW_FIRST,
  FG_RECENT_LAST_SEEN,
); // "-status,-severity,-delta,-last_seen_at"

